/**
 * qrcode.min.js — Minimal QR code generator for Smriti Pass 2.0.
 * Based on the qrcode-generator algorithm (Kazuhiko Arase).
 * Generates QR codes as SVG or Canvas — no external dependencies.
 *
 * Usage:
 *   SmritiQR.toSVG('https://smritipass.org/#tourist', { size: 200 })
 *   SmritiQR.toCanvas(canvasEl, 'data', { size: 200 })
 *   SmritiQR.toDataURL('data', { size: 200 }) → data:image/svg+xml;...
 */

const SmritiQR = (() => {
  'use strict';

  // ── QR Code core ──────────────────────────────────────────────

  // Error correction levels
  const EC_L = 1, EC_M = 0, EC_Q = 3, EC_H = 2;

  // Mode indicators
  const MODE_8BIT = 4;

  // Alignment pattern positions by version
  const ALIGN_POS = [
    [], [6,18], [6,22], [6,26], [6,30], [6,34],
    [6,22,38], [6,24,42], [6,26,46], [6,28,50], [6,30,54],
    [6,32,58], [6,34,62], [6,26,46,66], [6,26,48,70],
    [6,26,50,74], [6,30,58,86], [6,34,62,90], [6,28,50,72,94],
    [6,26,50,74,98], [6,30,54,78,102], [6,28,54,80,106],
    [6,32,58,84,110], [6,30,58,86,114], [6,34,62,90,118],
    [6,26,50,74,98,122], [6,30,54,78,102,126], [6,26,52,78,104,130],
    [6,30,56,82,108,134], [6,34,60,86,112,138], [6,30,58,86,114,142],
    [6,34,62,90,118,146], [6,30,54,78,102,126,150], [6,24,50,76,102,128,154],
    [6,28,54,80,106,132,158], [6,32,58,84,110,136,162], [6,26,54,82,110,138,166],
    [6,30,58,86,114,142,170]
  ];

  // Capacity table (version → max bytes for EC_M, 8-bit mode) — versions 1–10
  const CAPACITY = [0, 16, 28, 44, 64, 86, 108, 124, 154, 182, 216];

  // Number of EC codewords per block for versions 1-10 at EC_M
  const EC_CODEWORDS = [0, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26];
  const NUM_BLOCKS   = [0,  1,  1,  1,  2,  2,  4,  4,  4,  4,  4];

  // Format info for EC_M (mask 0-7)
  const FORMAT_INFO = [
    0x5412, 0x5125, 0x5E7C, 0x5B4B, 0x45F9, 0x40CE, 0x4F97, 0x4AA0
  ];

  // GF(256) arithmetic
  const EXP_TABLE = new Uint8Array(256);
  const LOG_TABLE = new Uint8Array(256);
  (function() {
    let x = 1;
    for (let i = 0; i < 255; i++) {
      EXP_TABLE[i] = x;
      LOG_TABLE[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11D;
    }
    EXP_TABLE[255] = EXP_TABLE[0];
  })();

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP_TABLE[(LOG_TABLE[a] + LOG_TABLE[b]) % 255];
  }

  // Generate RS error correction codewords
  function rsEncode(data, ecCount) {
    const gen = new Uint8Array(ecCount + 1);
    gen[0] = 1;
    for (let i = 0; i < ecCount; i++) {
      for (let j = i + 1; j >= 1; j--) {
        gen[j] = gen[j] ^ gfMul(gen[j - 1], EXP_TABLE[i]);
      }
    }
    const result = new Uint8Array(ecCount);
    const msg = new Uint8Array(data.length + ecCount);
    msg.set(data);
    for (let i = 0; i < data.length; i++) {
      const coef = msg[i];
      if (coef !== 0) {
        for (let j = 0; j <= ecCount; j++) {
          msg[i + j] ^= gfMul(gen[j], coef);
        }
      }
    }
    result.set(msg.subarray(data.length));
    return result;
  }

  // Determine the best version for data length
  function bestVersion(len) {
    for (let v = 1; v <= 10; v++) {
      if (len <= CAPACITY[v]) return v;
    }
    return 10; // clamp
  }

  // Create the data codewords
  function encodeData(text) {
    const bytes = new TextEncoder().encode(text);
    const version = bestVersion(bytes.length);
    const totalCW = CAPACITY[version] + EC_CODEWORDS[version] * NUM_BLOCKS[version];
    const dataCW  = CAPACITY[version];

    // Build bit stream: mode (4 bits) + count (8 or 16 bits) + data
    const bits = [];
    function pushBits(val, len) {
      for (let i = len - 1; i >= 0; i--) bits.push((val >> i) & 1);
    }
    pushBits(MODE_8BIT, 4);
    pushBits(bytes.length, version < 10 ? 8 : 16);
    for (const b of bytes) pushBits(b, 8);

    // Terminator
    const termLen = Math.min(4, dataCW * 8 - bits.length);
    pushBits(0, termLen);

    // Pad to byte boundary
    while (bits.length % 8 !== 0) bits.push(0);

    // Pad codewords
    const pads = [0xEC, 0x11];
    let pi = 0;
    while (bits.length < dataCW * 8) {
      pushBits(pads[pi], 8);
      pi = 1 - pi;
    }

    // Convert to bytes
    const data = new Uint8Array(dataCW);
    for (let i = 0; i < dataCW; i++) {
      let byte = 0;
      for (let b = 0; b < 8; b++) byte = (byte << 1) | (bits[i * 8 + b] || 0);
      data[i] = byte;
    }

    return { version, data };
  }

  // Place modules on the matrix
  function createMatrix(version, data) {
    const size = version * 4 + 17;
    const matrix = Array.from({ length: size }, () => new Int8Array(size)); // 0=unset, 1=dark, -1=light
    const reserved = Array.from({ length: size }, () => new Uint8Array(size));

    // Helper to set a module
    function set(r, c, dark) {
      if (r >= 0 && r < size && c >= 0 && c < size) {
        matrix[r][c] = dark ? 1 : -1;
        reserved[r][c] = 1;
      }
    }

    // Finder patterns (3 corners)
    function finderPattern(row, col) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const inOuter = r >= 0 && r <= 6 && c >= 0 && c <= 6;
          const inInner = r >= 2 && r <= 4 && c >= 2 && c <= 4;
          const onBorder = r === 0 || r === 6 || c === 0 || c === 6;
          if (r >= -1 && r <= 7 && c >= -1 && c <= 7) {
            set(row + r, col + c, inOuter && (onBorder || inInner));
          }
        }
      }
    }
    finderPattern(0, 0);
    finderPattern(0, size - 7);
    finderPattern(size - 7, 0);

    // Timing patterns
    for (let i = 8; i < size - 8; i++) {
      set(6, i, i % 2 === 0);
      set(i, 6, i % 2 === 0);
    }

    // Alignment patterns
    if (version >= 2) {
      const positions = ALIGN_POS[version - 1];
      for (const r of positions) {
        for (const c of positions) {
          if (reserved[r][c]) continue;
          for (let dr = -2; dr <= 2; dr++) {
            for (let dc = -2; dc <= 2; dc++) {
              set(r + dr, c + dc,
                Math.abs(dr) === 2 || Math.abs(dc) === 2 || (dr === 0 && dc === 0));
            }
          }
        }
      }
    }

    // Dark module
    set(size - 8, 8, true);

    // Reserve format info areas
    for (let i = 0; i < 8; i++) {
      if (!reserved[8][i]) { reserved[8][i] = 1; matrix[8][i] = -1; }
      if (!reserved[8][size - 1 - i]) { reserved[8][size - 1 - i] = 1; matrix[8][size - 1 - i] = -1; }
      if (!reserved[i][8]) { reserved[i][8] = 1; matrix[i][8] = -1; }
      if (!reserved[size - 1 - i][8]) { reserved[size - 1 - i][8] = 1; matrix[size - 1 - i][8] = -1; }
    }
    if (!reserved[8][8]) { reserved[8][8] = 1; matrix[8][8] = -1; }

    // EC encoding
    const ecCount  = EC_CODEWORDS[version];
    const nBlocks  = NUM_BLOCKS[version];
    const dataCWPerBlock = Math.floor(data.length / nBlocks);
    const dataBlocks = [];
    const ecBlocks = [];
    let offset = 0;
    for (let b = 0; b < nBlocks; b++) {
      const blockData = data.subarray(offset, offset + dataCWPerBlock);
      offset += dataCWPerBlock;
      dataBlocks.push(blockData);
      ecBlocks.push(rsEncode(blockData, ecCount));
    }

    // Interleave
    const interleaved = [];
    for (let i = 0; i < dataCWPerBlock; i++) {
      for (let b = 0; b < nBlocks; b++) interleaved.push(dataBlocks[b][i]);
    }
    for (let i = 0; i < ecCount; i++) {
      for (let b = 0; b < nBlocks; b++) interleaved.push(ecBlocks[b][i]);
    }

    // Convert to bit stream
    const allBits = [];
    for (const byte of interleaved) {
      for (let bit = 7; bit >= 0; bit--) allBits.push((byte >> bit) & 1);
    }

    // Place data bits
    let bitIdx = 0;
    let upward = true;
    for (let col = size - 1; col >= 0; col -= 2) {
      if (col === 6) col = 5; // skip timing column
      const rows = upward
        ? Array.from({ length: size }, (_, i) => size - 1 - i)
        : Array.from({ length: size }, (_, i) => i);
      for (const row of rows) {
        for (let dc = 0; dc <= 1; dc++) {
          const c = col - dc;
          if (c < 0 || reserved[row][c]) continue;
          if (bitIdx < allBits.length) {
            matrix[row][c] = allBits[bitIdx] ? 1 : -1;
          } else {
            matrix[row][c] = -1;
          }
          bitIdx++;
        }
      }
      upward = !upward;
    }

    // Apply mask pattern 0 (checkerboard) & format info
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (!reserved[r][c] || (!reservedFormatArea(r, c, size))) {
          // Not reserved for format info — apply mask
        }
      }
    }

    // Apply mask 0: (row + col) % 2 === 0
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (reservedFixed(r, c, size, version)) continue;
        if ((r + c) % 2 === 0) {
          matrix[r][c] = matrix[r][c] === 1 ? -1 : 1;
        }
      }
    }

    // Write format info (EC_M, mask 0)
    const fmtInfo = FORMAT_INFO[0];
    const fmtBits = [];
    for (let i = 14; i >= 0; i--) fmtBits.push((fmtInfo >> i) & 1);

    // Format bits around top-left finder
    const TL_POS_ROW = [0,1,2,3,4,5,7,8,8,8,8,8,8,8,8];
    const TL_POS_COL = [8,8,8,8,8,8,8,8,7,5,4,3,2,1,0];
    for (let i = 0; i < 15; i++) {
      matrix[TL_POS_ROW[i]][TL_POS_COL[i]] = fmtBits[i] ? 1 : -1;
    }

    // Format bits around other finders
    for (let i = 0; i < 7; i++) {
      matrix[size - 1 - i][8] = fmtBits[i] ? 1 : -1;
    }
    for (let i = 7; i < 15; i++) {
      matrix[8][size - 15 + i] = fmtBits[i] ? 1 : -1;
    }

    return { matrix, size };

    function reservedFixed(r, c, size, ver) {
      // Finder + separator
      if (r < 9 && c < 9) return true;
      if (r < 9 && c >= size - 8) return true;
      if (r >= size - 8 && c < 9) return true;
      // Timing
      if (r === 6 || c === 6) return true;
      // Alignment
      if (ver >= 2) {
        const positions = ALIGN_POS[ver - 1];
        for (const ar of positions) {
          for (const ac of positions) {
            if (Math.abs(r - ar) <= 2 && Math.abs(c - ac) <= 2) return true;
          }
        }
      }
      // Dark module
      if (r === size - 8 && c === 8) return true;
      return false;
    }

    function reservedFormatArea(r, c, size) {
      if (r === 8 && (c <= 8 || c >= size - 8)) return true;
      if (c === 8 && (r <= 8 || r >= size - 8)) return true;
      return false;
    }
  }

  // ── Rendering ─────────────────────────────────────────────────

  /**
   * Generate QR code as an SVG string.
   * @param {string} text — data to encode
   * @param {object} [opts]
   * @param {number} [opts.size=200] — SVG width/height in px
   * @param {string} [opts.fg='#1a1a2e'] — foreground colour
   * @param {string} [opts.bg='#ffffff'] — background colour
   * @param {number} [opts.padding=2] — quiet zone in modules
   * @returns {string} SVG markup
   */
  function toSVG(text, opts = {}) {
    const { size = 200, fg = '#1a1a2e', bg = '#ffffff', padding = 2 } = opts;
    const { data, version } = encodeData(text);
    const { matrix, size: matSize } = createMatrix(version, data);

    const totalMods = matSize + padding * 2;
    const modSize = size / totalMods;

    let svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}">`;
    svg += `<rect width="${size}" height="${size}" fill="${bg}"/>`;

    for (let r = 0; r < matSize; r++) {
      for (let c = 0; c < matSize; c++) {
        if (matrix[r][c] === 1) {
          const x = (c + padding) * modSize;
          const y = (r + padding) * modSize;
          svg += `<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${modSize.toFixed(2)}" height="${modSize.toFixed(2)}" fill="${fg}"/>`;
        }
      }
    }

    svg += '</svg>';
    return svg;
  }

  /**
   * Render QR code onto a canvas element.
   */
  function toCanvas(canvas, text, opts = {}) {
    const { size = 200, fg = '#1a1a2e', bg = '#ffffff', padding = 2 } = opts;
    const { data, version } = encodeData(text);
    const { matrix, size: matSize } = createMatrix(version, data);

    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const totalMods = matSize + padding * 2;
    const modSize = size / totalMods;

    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = fg;

    for (let r = 0; r < matSize; r++) {
      for (let c = 0; c < matSize; c++) {
        if (matrix[r][c] === 1) {
          ctx.fillRect(
            (c + padding) * modSize,
            (r + padding) * modSize,
            modSize, modSize
          );
        }
      }
    }
  }

  /**
   * Generate a data URL for the QR code SVG.
   */
  function toDataURL(text, opts = {}) {
    const svg = toSVG(text, opts);
    return 'data:image/svg+xml;base64,' + btoa(unescape(encodeURIComponent(svg)));
  }

  /**
   * Create an IMG element with the QR code.
   */
  function toImage(text, opts = {}) {
    const img = document.createElement('img');
    img.src = toDataURL(text, opts);
    img.alt = 'QR Code — ' + text;
    img.className = 'smriti-qr-code';
    return img;
  }

  return { toSVG, toCanvas, toDataURL, toImage };
})();
